-- Add inferred groups once; preserve every manual group and all product/booking amounts.
UPDATE menu_catalog SET data=json_set(data,'$.dishes',json((
 WITH RECURSIVE folded(pos,value,name,step) AS (
 SELECT CAST(key AS INTEGER),value,json_extract(value,'$.name'),0 FROM json_each(menu_catalog.data,'$.dishes')
 UNION ALL
 SELECT pos,value,CASE WHEN step<147 THEN replace(name,substr('àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđÀÁẠẢÃÂẦẤẬẨẪĂẰẮẶẲẴÈÉẸẺẼÊỀẾỆỂỄÌÍỊỈĨÒÓỌỎÕÔỒỐỘỔỖƠỜỚỢỞỠÙÚỤỦŨƯỪỨỰỬỮỲÝỴỶỸĐ-_/().,:;&+–—',step+1,1),substr('aaaaaaaaaaaaaaaaaeeeeeeeeeeeiiiiiooooooooooooooooouuuuuuuuuuuyyyyydaaaaaaaaaaaaaaaaaeeeeeeeeeeeiiiiiooooooooooooooooouuuuuuuuuuuyyyyyd             ',step+1,1)) ELSE replace(name,'  ',' ') END,step+1 FROM folded WHERE step<155
 )
 SELECT json_group_array(json(item)) FROM (
 SELECT CASE WHEN trim(COALESCE(json_extract(value,'$.category'),''))<>'' THEN value ELSE json_set(value,'$.category',CASE
 WHEN instr(' '||trim(lower(name))||' ',' bim bim ')>0 OR instr(' '||trim(lower(name))||' ',' huong duong ')>0 OR instr(' '||trim(lower(name))||' ',' snack ')>0 OR instr(' '||trim(lower(name))||' ',' kho ga ')>0 OR instr(' '||trim(lower(name))||' ',' kho bo ')>0 OR instr(' '||trim(lower(name))||' ',' khoai tay chien ')>0 OR instr(' '||trim(lower(name))||' ',' hat dieu ')>0 OR instr(' '||trim(lower(name))||' ',' bap rang ')>0 OR instr(' '||trim(lower(name))||' ',' bong ngo ')>0 THEN 'Ăn vặt'
WHEN instr(' '||trim(lower(name))||' ',' sot vang ')>0 OR instr(' '||trim(lower(name))||' ',' hap bia ')>0 OR instr(' '||trim(lower(name))||' ',' sot ruou ')>0 THEN 'Món ăn'
WHEN instr(' '||trim(lower(name))||' ',' nuoc ep ')>0 OR instr(' '||trim(lower(name))||' ',' ep ')>0 OR instr(' '||trim(lower(name))||' ',' nuoc trai cay ')>0 OR instr(' '||trim(lower(name))||' ',' juice ')>0 THEN 'Nước ép'
WHEN instr(' '||trim(lower(name))||' ',' sinh to ')>0 OR instr(' '||trim(lower(name))||' ',' smoothie ')>0 THEN 'Sinh tố'
WHEN instr(' '||trim(lower(name))||' ',' ca phe ')>0 OR instr(' '||trim(lower(name))||' ',' cafe ')>0 OR instr(' '||trim(lower(name))||' ',' coffee ')>0 OR instr(' '||trim(lower(name))||' ',' espresso ')>0 OR instr(' '||trim(lower(name))||' ',' latte ')>0 OR instr(' '||trim(lower(name))||' ',' cappuccino ')>0 OR instr(' '||trim(lower(name))||' ',' bac xiu ')>0 THEN 'Cà phê'
WHEN instr(' '||trim(lower(name))||' ',' tra ')>0 OR instr(' '||trim(lower(name))||' ',' tea ')>0 OR instr(' '||trim(lower(name))||' ',' matcha ')>0 THEN 'Trà'
WHEN instr(' '||trim(lower(name))||' ',' ruou ')>0 OR instr(' '||trim(lower(name))||' ',' vang ')>0 OR instr(' '||trim(lower(name))||' ',' vodka ')>0 OR instr(' '||trim(lower(name))||' ',' whisky ')>0 OR instr(' '||trim(lower(name))||' ',' whiskey ')>0 OR instr(' '||trim(lower(name))||' ',' chivas ')>0 OR instr(' '||trim(lower(name))||' ',' hennessy ')>0 OR instr(' '||trim(lower(name))||' ',' soju ')>0 OR instr(' '||trim(lower(name))||' ',' cognac ')>0 THEN 'Rượu'
WHEN instr(' '||trim(lower(name))||' ',' bia ')>0 OR instr(' '||trim(lower(name))||' ',' beer ')>0 OR instr(' '||trim(lower(name))||' ',' heineken ')>0 OR instr(' '||trim(lower(name))||' ',' tiger ')>0 OR instr(' '||trim(lower(name))||' ',' hanoi ')>0 OR instr(' '||trim(lower(name))||' ',' budweiser ')>0 OR instr(' '||trim(lower(name))||' ',' sai gon ')>0 OR instr(' '||trim(lower(name))||' ',' saigon ')>0 OR instr(' '||trim(lower(name))||' ',' carlsberg ')>0 THEN 'Bia'
WHEN instr(' '||trim(lower(name))||' ',' nuoc loc ')>0 OR instr(' '||trim(lower(name))||' ',' nuoc suoi ')>0 OR instr(' '||trim(lower(name))||' ',' nuoc khoang ')>0 OR instr(' '||trim(lower(name))||' ',' nuoc ngot ')>0 OR instr(' '||trim(lower(name))||' ',' coca ')>0 OR instr(' '||trim(lower(name))||' ',' pepsi ')>0 OR instr(' '||trim(lower(name))||' ',' sprite ')>0 OR instr(' '||trim(lower(name))||' ',' 7up ')>0 OR instr(' '||trim(lower(name))||' ',' lavie ')>0 OR instr(' '||trim(lower(name))||' ',' aquafina ')>0 OR instr(' '||trim(lower(name))||' ',' revive ')>0 OR instr(' '||trim(lower(name))||' ',' redbull ')>0 OR instr(' '||trim(lower(name))||' ',' red bull ')>0 OR instr(' '||trim(lower(name))||' ',' sting ')>0 OR instr(' '||trim(lower(name))||' ',' bo huc ')>0 OR instr(' '||trim(lower(name))||' ',' sua chua ')>0 OR instr(' '||trim(lower(name))||' ',' sua tuoi ')>0 OR instr(' '||trim(lower(name))||' ',' cacao ')>0 OR instr(' '||trim(lower(name))||' ',' nuoc dua ')>0 OR instr(' '||trim(lower(name))||' ',' dua xiem ')>0 OR instr(' '||trim(lower(name))||' ',' chanh muoi ')>0 OR instr(' '||trim(lower(name))||' ',' man ngam ')>0 THEN 'Đồ uống khác'
 ELSE 'Món ăn' END) END AS item FROM folded WHERE step=155 ORDER BY pos
 )
))),version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE EXISTS(SELECT 1 FROM json_each(menu_catalog.data,'$.dishes') WHERE trim(COALESCE(json_extract(value,'$.category'),''))='');
